def export_guide_pdf(path):
    from pathlib import Path
    from PyQt5.QtGui import QTextDocument, QFont
    from PyQt5.QtPrintSupport import QPrinter
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    printer = QPrinter(QPrinter.HighResolution)
    printer.setOutputFormat(QPrinter.PdfFormat)
    printer.setPaperSize(QPrinter.A4)
    printer.setPageMargins(17, 17, 17, 18, QPrinter.Millimeter)
    printer.setDocName("Smart Order — Руководство пользователя")
    printer.setOutputFileName(str(path))
    document = QTextDocument()
    document.setDefaultFont(QFont("DejaVu Sans" if __import__('os').name != 'nt' else "Segoe UI", 10))
    printable = USER_GUIDE_HTML.replace("max-width:960px;margin:32px auto;padding:0 28px", "max-width:none;margin:0;padding:0")
    document.setHtml(printable)
    document.print_(printer)
    if not path.is_file() or path.stat().st_size < 1000:
        raise OSError("Не удалось сохранить руководство в PDF.")
    return path
